import os
from datetime import datetime, timezone, timedelta
from typing import Any, Dict, List, Optional

import requests


class DatadogLogsClient:
    def __init__(
        self,
        api_key: Optional[str] = None,
        app_key: Optional[str] = None,
        site: Optional[str] = None,
        timeout: int = 30,
    ) -> None:
        self.api_key = api_key or os.environ["DATADOG_API_KEY"]
        self.app_key = app_key or os.environ["DATADOG_APP_KEY"]
        self.site = site or os.environ.get("DATADOG_SITE", "datadoghq.com")
        self.base_url = f"https://api.{self.site}"
        self.timeout = timeout

    def query_recent_errors(
        self,
        severity: str = "error",
        minutes_back: int = 15,
        limit: int = 100,
        service: Optional[str] = None,
        index: str = "*",
    ) -> List[Dict[str, Any]]:
        end = datetime.now(timezone.utc)
        start = end - timedelta(minutes=minutes_back)

        query_parts = [f"status:{severity}"]
        if service:
            query_parts.append(f"service:{service}")

        payload = {
            "filter": {
                "from": start.isoformat().replace("+00:00", "Z"),
                "to": end.isoformat().replace("+00:00", "Z"),
                "query": " ".join(query_parts),
                "indexes": [index],
            },
            "sort": "timestamp",
            "page": {
                "limit": limit,
            },
        }

        headers = {
            "DD-API-KEY": self.api_key,
            "DD-APPLICATION-KEY": self.app_key,
            "Content-Type": "application/json",
            "Accept": "application/json",
        }

        response = requests.post(
            f"{self.base_url}/api/v2/logs/events/search",
            headers=headers,
            json=payload,
            timeout=self.timeout,
        )
        response.raise_for_status()
        data = response.json()

        results: List[Dict[str, Any]] = []
        for item in data.get("data", []):
            attrs = item.get("attributes", {})
            results.append(
                {
                    "id": item.get("id"),
                    "timestamp": attrs.get("timestamp"),
                    "message": attrs.get("message"),
                    "status": attrs.get("status"),
                    "service": attrs.get("service"),
                    "host": attrs.get("host"),
                    "tags": attrs.get("tags", []),
                    "raw": item,
                }
            )
        return results


def query_recent_error_logs(
    severity: str = "error",
    start_time: Optional[datetime] = None,
    end_time: Optional[datetime] = None,
    limit: int = 100,
    service: Optional[str] = None,
    index: str = "*",
) -> List[Dict[str, Any]]:
    client = DatadogLogsClient()

    if end_time is None:
        end_time = datetime.now(timezone.utc)
    if start_time is None:
        start_time = end_time - timedelta(minutes=15)

    if start_time.tzinfo is None:
        start_time = start_time.replace(tzinfo=timezone.utc)
    if end_time.tzinfo is None:
        end_time = end_time.replace(tzinfo=timezone.utc)

    query_parts = [f"status:{severity}"]
    if service:
        query_parts.append(f"service:{service}")

    payload = {
        "filter": {
            "from": start_time.isoformat().replace("+00:00", "Z"),
            "to": end_time.isoformat().replace("+00:00", "Z"),
            "query": " ".join(query_parts),
            "indexes": [index],
        },
        "sort": "timestamp",
        "page": {
            "limit": limit,
        },
    }

    headers = {
        "DD-API-KEY": client.api_key,
        "DD-APPLICATION-KEY": client.app_key,
        "Content-Type": "application/json",
        "Accept": "application/json",
    }

    response = requests.post(
        f"{client.base_url}/api/v2/logs/events/search",
        headers=headers,
        json=payload,
        timeout=client.timeout,
    )
    response.raise_for_status()
    body = response.json()

    return [
        {
            "id": item.get("id"),
            "timestamp": item.get("attributes", {}).get("timestamp"),
            "message": item.get("attributes", {}).get("message"),
            "status": item.get("attributes", {}).get("status"),
            "service": item.get("attributes", {}).get("service"),
            "host": item.get("attributes", {}).get("host"),
            "tags": item.get("attributes", {}).get("tags", []),
            "raw": item,
        }
        for item in body.get("data", [])
    ]
